Here is a complete, ready-to-play browser game built in a single HTML file. 

Save the code below as **`cat_game.html`** on your computer, double-click the file to open it in any web browser, and play.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Cat Catch Fish</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      user-select: none;
    }
    body {
      background: #1e1e2f;
      color: #fff;
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      overflow: hidden;
    }
    #game-container {
      position: relative;
      border: 4px solid #4a4a75;
      border-radius: 12px;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
      background: linear-gradient(to bottom, #87ceeb 0%, #e0f6ff 80%, #90ee90 80%, #4caf50 100%);
      overflow: hidden;
    }
    canvas {
      display: block;
    }
    #ui-overlay {
      position: absolute;
      top: 12px;
      left: 16px;
      right: 16px;
      display: flex;
      justify-content: space-between;
      font-size: 20px;
      font-weight: bold;
      color: #2c3e50;
      text-shadow: 1px 1px 0 rgba(255, 255, 255, 0.7);
      pointer-events: none;
    }
    #game-over-screen {
      position: absolute;
      inset: 0;
      background: rgba(0, 0, 0, 0.75);
      display: none;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      color: #fff;
      text-align: center;
    }
    #game-over-screen h1 {
      font-size: 42px;
      margin-bottom: 8px;
      color: #ff6b6b;
    }
    #game-over-screen p {
      font-size: 20px;
      margin-bottom: 20px;
    }
    button {
      padding: 12px 28px;
      font-size: 18px;
      font-weight: bold;
      color: #fff;
      background: #4caf50;
      border: none;
      border-radius: 25px;
      cursor: pointer;
      transition: transform 0.1s, background-color 0.2s;
    }
    button:hover {
      background: #45a049;
      transform: scale(1.05);
    }
    .instructions {
      margin-top: 12px;
      font-size: 14px;
      color: #aaa;
    }
  </style>
</head>
<body>

  <div id="game-container">
    <div id="ui-overlay">
      <div id="score-display">Score: 0</div>
      <div id="lives-display">Lives: ❤️❤️❤️</div>
    </div>
    <canvas id="gameCanvas" width="480" height="600"></canvas>
    <div id="game-over-screen">
      <h1>Game Over!</h1>
      <p id="final-score">You caught 0 fish!</p>
      <button id="restart-btn">Play Again</button>
    </div>
  </div>

  <p class="instructions">Use <strong>Left / Right Arrow</strong> or <strong>A / D</strong> keys to move (or drag/swipe with your mouse/finger).</p>

  <script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const scoreDisplay = document.getElementById('score-display');
    const livesDisplay = document.getElementById('lives-display');
    const gameOverScreen = document.getElementById('game-over-screen');
    const finalScore = document.getElementById('final-score');
    const restartBtn = document.getElementById('restart-btn');

    let score = 0;
    let lives = 3;
    let gameOver = false;
    let keys = {};
    let fishList = [];
    let spawnTimer = 0;
    let spawnInterval = 60; // frames between spawns
    let difficultyMultiplier = 1;

    // Cat player object
    const cat = {
      x: canvas.width / 2 - 25,
      y: canvas.height - 85,
      width: 50,
      height: 50,
      speed: 7,
      facingLeft: false
    };

    // Keyboard handlers
    window.addEventListener('keydown', (e) => { keys[e.key] = true; });
    window.addEventListener('keyup', (e) => { keys[e.key] = false; });

    // Mouse / Touch drag controls
    function setCatPositionFromPointer(clientX) {
      const rect = canvas.getBoundingClientRect();
      const pointerX = clientX - rect.left;
      cat.x = Math.max(0, Math.min(canvas.width - cat.width, pointerX - cat.width / 2));
    }

    let isPointerDown = false;
    canvas.addEventListener('mousedown', (e) => { isPointerDown = true; setCatPositionFromPointer(e.clientX); });
    window.addEventListener('mousemove', (e) => { if (isPointerDown) setCatPositionFromPointer(e.clientX); });
    window.addEventListener('mouseup', () => { isPointerDown = false; });

    canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      setCatPositionFromPointer(e.touches[0].clientX);
    }, { passive: false });

    function spawnFish() {
      const types = [
        { emoji: '🐟', points: 1, speed: 3 },
        { emoji: '🐠', points: 2, speed: 4 },
        { emoji: '🐡', points: 3, speed: 5 },
        { emoji: '🥾', points: -1, isBoot: true, speed: 3.5 } // boot hazard
      ];

      // 15% chance of an old boot falling
      const isBoot = Math.random() < 0.15;
      const fishType = isBoot ? types[3] : types[Math.floor(Math.random() * 3)];

      fishList.push({
        x: Math.random() * (canvas.width - 40) + 10,
        y: -30,
        size: 32,
        speed: (fishType.speed + Math.random()) * difficultyMultiplier,
        type: fishType
      });
    }

    function checkCollision(catBox, fishBox) {
      return (
        catBox.x < fishBox.x + fishBox.size &&
        catBox.x + catBox.width > fishBox.x &&
        catBox.y < fishBox.y + fishBox.size &&
        catBox.y + catBox.height > fishBox.y
      );
    }

    function update() {
      if (gameOver) return;

      // Handle keyboard movement
      if (keys['ArrowLeft'] || keys['a'] || keys['A']) {
        cat.x -= cat.speed;
        cat.facingLeft = true;
      }
      if (keys['ArrowRight'] || keys['d'] || keys['D']) {
        cat.x += cat.speed;
        cat.facingLeft = false;
      }

      // Keep cat inside canvas
      cat.x = Math.max(0, Math.min(canvas.width - cat.width, cat.x));

      // Spawning
      spawnTimer++;
      if (spawnTimer >= spawnInterval) {
        spawnFish();
        spawnTimer = 0;
        // Gradually increase difficulty over time
        difficultyMultiplier = 1 + score * 0.03;
        spawnInterval = Math.max(25, 60 - Math.floor(score / 2));
      }

      // Update falling items
      for (let i = fishList.length - 1; i >= 0; i--) {
        const item = fishList[i];
        item.y += item.speed;

        // Collision with cat
        if (checkCollision(cat, item)) {
          if (item.type.isBoot) {
            lives--;
          } else {
            score += item.type.points;
          }
          fishList.splice(i, 1);
          updateUI();
          if (lives <= 0) triggerGameOver();
          continue;
        }

        // Missed item reaches bottom
        if (item.y > canvas.height - 40) {
          if (!item.type.isBoot) {
            lives--;
            updateUI();
            if (lives <= 0) triggerGameOver();
          }
          fishList.splice(i, 1);
        }
      }
    }

    function updateUI() {
      scoreDisplay.innerText = `Score: ${score}`;
      livesDisplay.innerText = 'Lives: ' + '❤️'.repeat(Math.max(0, lives));
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Draw clouds
      ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
      ctx.beginPath();
      ctx.arc(80, 80, 25, 0, Math.PI * 2);
      ctx.arc(115, 75, 35, 0, Math.PI * 2);
      ctx.arc(150, 80, 25, 0, Math.PI * 2);
      ctx.fill();

      ctx.beginPath();
      ctx.arc(340, 120, 20, 0, Math.PI * 2);
      ctx.arc(370, 115, 30, 0, Math.PI * 2);
      ctx.arc(400, 120, 20, 0, Math.PI * 2);
      ctx.fill();

      // Draw falling fish and hazards
      ctx.font = '32px sans-serif';
      ctx.textAlign = 'center';
      for (const item of fishList) {
        ctx.fillText(item.type.emoji, item.x + item.size / 2, item.y + item.size);
      }

      // Draw cat
      ctx.save();
      ctx.translate(cat.x + cat.width / 2, cat.y + cat.height / 2);
      if (cat.facingLeft) {
        ctx.scale(-1, 1); // Flip horizontally when moving left
      }
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🐱', 0, 0);
      ctx.restore();
    }

    function gameLoop() {
      update();
      draw();
      if (!gameOver) {
        requestAnimationFrame(gameLoop);
      }
    }

    function triggerGameOver() {
      gameOver = true;
      finalScore.innerText = `You caught ${score} fish!`;
      gameOverScreen.style.display = 'flex';
    }

    function resetGame() {
      score = 0;
      lives = 3;
      fishList = [];
      difficultyMultiplier = 1;
      spawnInterval = 60;
      gameOver = false;
      updateUI();
      gameOverScreen.style.display = 'none';
      requestAnimationFrame(gameLoop);
    }

    restartBtn.addEventListener('click', resetGame);

    // Initial start
    updateUI();
    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
```

**Game Features**
* **Fish Variety:** Catches 🐟 (1 pt), 🐠 (2 pts), and 🐡 (3 pts).
* **Hazards:** Avoid the muddy boots (🥾)—catching one takes away a heart.
* **Escalating Speed:** The fish drop faster and spawn more frequently as your score climbs.
* **Controls:** Works with Arrow Keys, `A`/`D`, or by dragging your mouse/finger across the screen.

