    function setCatPositionFromPointer(clientX) {
      const rect = canvas.getBoundingClientRect();
      const pointerX = clientX - rect.left;
      cat.x = Math.max(0, Math.min(canvas.width - cat.width, pointerX - cat.width / 2));
    }

    let isPointerDown = false;
    canvas.addEventListener('mousedown', (e) => { isPointerDown = true; setCatPositionFromPointer(e.clientX); });
    window.addEventListener('mousemove', (e) => { if (isPointerDown) setCatPositionFromPointer(e.clientX); });
    window.addEventListener('mouseup', () => { isPointerDown = false; });

    canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      setCatPositionFromPointer(e.touches[0].clientX);
    }, { passive: false });

    function spawnFish() {
      const roll = Math.random();

      let fishType;
      // 5% chance of rare golden fish
      if (roll < 0.05) {
        fishType = { emoji: '🐠', points: 10, speed: 5.5, isGolden: true };
      } else if (roll < 0.15) {
        fishType = { emoji: '🥾', points: -1, speed: 1.8, isBoot: true };
      } else if (roll < 0.50) {
        fishType = { emoji: '🐟', points: 1, speed: 1.7 };
      } else if (roll < 0.80) {
        fishType = { emoji: '🐡', points: 2, speed: 2.1 };
      } else {
        fishType = { emoji: '🦐', points: 3, speed: 2.5 };
      }

      fishList.push({
        x: Math.random() * (canvas.width - 50) + 10,
        y: -30,
        size: fishType.isGolden ? 40 : 36,
        speed: fishType.speed,
        type: fishType
      });
    }

    function checkCollision(catBox, fishBox) {
      return (
        catBox.x < fishBox.x + fishBox.size &&
        catBox.x + catBox.width > fishBox.x &&
        catBox.y < fishBox.y + fishBox.size &&
        catBox.y + catBox.height > fishBox.y
      );
    }

    function update() {
      if (gameOver) return;

      if (keys['ArrowLeft'] || keys['a'] || keys['A']) {
        cat.x -= cat.speed;
        cat.facingLeft = true;
      }
      if (keys['ArrowRight'] || keys['d'] || keys['D']) {
        cat.x += cat.speed;
        cat.facingLeft = false;
      }

      cat.x = Math.max(0, Math.min(canvas.width - cat.width, cat.x));

      spawnTimer++;
      if (spawnTimer >= spawnInterval) {
        spawnFish();
        spawnTimer = 0;
      }

      // Update sparkle trails
      for (let s = sparkles.length - 1; s >= 0; s--) {
        sparkles[s].life -= 0.05;
        if (sparkles[s].life <= 0) {
          sparkles.splice(s, 1);
        }
      }

      // Update falling items
      for (let i = fishList.length - 1; i >= 0; i--) {
        const item = fishList[i];
        item.y += item.speed;

        // Leave sparkles behind golden fish
        if (item.type.isGolden && Math.random() < 0.5) {
          sparkles.push({
            x: item.x + item.size / 2 + (Math.random() * 20 - 10),
            y: item.y + item.size / 2,
            size: Math.random() * 6 + 3,
            life: 1
          });
        }

        // Collision with cat
        if (checkCollision(cat, item)) {
          if (item.type.isBoot) {
            lives--;
          } else {
            score += item.type.points;
          }
          fishList.splice(i, 1);
          updateUI();
          if (lives <= 0) triggerGameOver();
          continue;
        }

        // Missed item reaches bottom
        if (item.y > canvas.height - 35) {
          // Missing a golden fish doesn't cost a life (just a missed bonus)
          if (!item.type.isBoot && !item.type.isGolden) {
            lives--;
            updateUI();
            if (lives <= 0) triggerGameOver();
          }
          fishList.splice(i, 1);
        }
      }
    }

    function updateUI() {
      scoreDisplay.innerText = `Score: ${score}`;
      livesDisplay.innerText = 'Lives: ' + '❤️'.repeat(Math.max(0, lives));
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Pinkish/white clouds
      ctx.fillStyle = 'rgba(255, 255, 255, 0.75)';
      ctx.beginPath();
      ctx.arc(80, 80, 25, 0, Math.PI * 2);
      ctx.arc(115, 75, 35, 0, Math.PI * 2);
      ctx.arc(150, 80, 25, 0, Math.PI * 2);
      ctx.fill();

      ctx.beginPath();
      ctx.arc(340, 110, 20, 0, Math.PI * 2);
      ctx.arc(370, 105, 30, 0, Math.PI * 2);
      ctx.arc(400, 110, 20, 0, Math.PI * 2);
      ctx.fill();

      // Sparkles
      for (const sp of sparkles) {
        ctx.fillStyle = `rgba(255, 215, 0, ${sp.life})`;
        ctx.beginPath();
        ctx.arc(sp.x, sp.y, sp.size, 0, Math.PI * 2);
        ctx.fill();
      }

      // Draw items
      ctx.textAlign = 'center';
      for (const item of fishList) {
        if (item.type.isGolden) {
          // Gold glow circle behind the golden fish
          ctx.fillStyle = 'rgba(255, 223, 0, 0.45)';
          ctx.beginPath();
          ctx.arc(item.x + item.size / 2, item.y + item.size / 2, 22, 0, Math.PI * 2);
          ctx.fill();

          ctx.font = '38px sans-serif';
          ctx.fillText('✨', item.x + item.size / 2, item.y + item.size - 6);
        } else {
          ctx.font = '34px sans-serif';
          ctx.fillText(item.type.emoji, item.x + item.size / 2, item.y + item.size);
        }
      }

      // Cat
      ctx.save();
      ctx.translate(cat.x + cat.width / 2, cat.y + cat.height / 2);
      if (cat.facingLeft) {
        ctx.scale(-1, 1);
      }
      ctx.font = '72px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🐱', 0, 0);
      ctx.restore();
    }

    function gameLoop() {
      update();
      draw();
      if (!gameOver) {
        requestAnimationFrame(gameLoop);
      }
    }

    function triggerGameOver() {
      gameOver = true;
      finalScore.innerText = `You caught ${score} points worth of fish!`;
      gameOverScreen.style.display = 'flex';
    }

    function resetGame() {
      score = 0;
      lives = 5;
      fishList = [];
      sparkles = [];
      spawnTimer = 0;
      gameOver = false;
      updateUI();
      gameOverScreen.style.display = 'none';
      requestAnimationFrame(gameLoop);
    }

    restartBtn.addEventListener('click', resetGame);

    updateUI();
    requestAnimationFrame(gameLoop);
  </script>
</body>
