      spawnTimer++;
      if (spawnTimer >= spawnInterval) {
        spawnItem();
        spawnTimer = 0;
        // Gradually increase difficulty
        speedMultiplier = Math.min(2.2, 1 + score / 350);
        spawnInterval = Math.max(25, 55 - Math.floor(score / 50));
      }

      // Update falling items
      for (let i = items.length - 1; i >= 0; i--) {
        const item = items[i];
        item.y += item.speed;

        // Caught by cat
        if (checkCollision(item)) {
          if (item.type === 'bomb') {
            lives--;
            livesDisplay.textContent = `❤️ Lives: ${lives}`;
            if (lives <= 0) {
