      if (keys['ArrowLeft'] || keys['a'] || keys['A']) {
        cat.x -= cat.speed;
        cat.facingLeft = true;
      }
      if (keys['ArrowRight'] || keys['d'] || keys['D']) {
        cat.x += cat.speed;
        cat.facingLeft = false;
      }
      cat.x = Math.max(0, Math.min(canvas.width - cat.width, cat.x));

      // Dog AI
      if (dog.scared) {
        // Run away to the far right edge of the screen!
        dog.x += dog.speed * 1.6;
        dog.facingLeft = false;
      } else if (dog.stunTimer > 0) {
        dog.stunTimer--;
      } else {
        // Standard Dog: hunt closest regular fish
        let target = null;
        let lowestY = -1;
        for (const item of items) {
          if (item.type !== 'bomb' && item.type !== 'rainbow' && item.y > lowestY) {
            lowestY = item.y;
            target = item;
          }
        }

        if (target) {
          const targetCenter = target.x + target.size / 2;
          const dogCenter = dog.x + dog.width / 2;
          if (dogCenter < targetCenter - 8) {
            dog.x += dog.speed;
            dog.facingLeft = false;
          } else if (dogCenter > targetCenter + 8) {
            dog.x -= dog.speed;
            dog.facingLeft = true;
          }
        }
      }
      dog.x = Math.max(-50, Math.min(canvas.width + 40, dog.x));

