        if (!dog.scared && dog.stunTimer === 0 && checkCollision(dog, item)) {
          if (item.type === 'bomb') {
            dog.stunTimer = 110;
            addAlert('Dizzy! 💫', dog.x + 25, dog.y - 15, '#ffb703');
          } else if (item.type !== 'rainbow') {
            addAlert('Stolen! 🐶', dog.x + 25, dog.y - 15, '#ff4d6d');
          }
          items.splice(i, 1);
          continue;
        }

        // Cat collision
        if (checkCollision(cat, item)) {
          if (item.type === 'rainbow') {
            megaTimeLeft = 480; // ~8 seconds
            score += item.points;
            scoreDisplay.textContent = `🐟 Score: ${score}`;
            addAlert('MEGA CAT! 🌈✨', cat.x + cat.width / 2, cat.y - 20, '#7209b7');
          } else if (item.type === 'bomb') {
            if (isMega) {
              // Super Cat crushes bombs harmlessly for bonus points!
              score += 20;
              scoreDisplay.textContent = `🐟 Score: ${score}`;
              addAlert('BOMB CRUSH! +20 💥', cat.x + cat.width / 2, cat.y - 15, '#f72585');
            } else {
              lives--;
              livesDisplay.textContent = `❤️ Lives: ${lives}`;
              addAlert('-1 Life! 💥', cat.x + 25, cat.y - 15, '#d90429');
              if (lives <= 0) {
                gameOver();
                return;
              }
            }
          } else {
            // Normal or Golden fish
            const earned = isMega ? item.points * 2 : item.points;
            score += earned;
            scoreDisplay.textContent = `🐟 Score: ${score}`;
            addAlert(`+${earned}`, cat.x + cat.width / 2, cat.y - 15, isMega ? '#ffd166' : '#52b788');
          }
          items.splice(i, 1);
          continue;
        }

        // Ground Miss
        if (item.y > canvas.height - 20) {
          if (item.type === 'fish' && !isMega) {
            lives--;
            livesDisplay.textContent = `❤️ Lives: ${lives}`;
            addAlert('Missed! ❌', item.x, canvas.height - 30, '#ef233c');
            if (lives <= 0) {
              gameOver();
              return;
            }
          }
          items.splice(i, 1);
        }
      }

      // Alerts
      for (let i = alerts.length - 1; i >= 0; i--) {
        alerts[i].y -= 1.2;
        alerts[i].alpha -= 0.025;
        if (alerts[i].alpha <= 0) alerts.splice(i, 1);
      }
    }

    function renderSprite(symbol, x, y, width, height, facingLeft, fontSize = 42) {
      ctx.save();
      ctx.font = `${fontSize}px sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      if (facingLeft) {
        ctx.translate(x + width / 2, y + height / 2);
        ctx.scale(-1, 1);
        ctx.fillText(symbol, 0, 0);
      } else {
        ctx.fillText(symbol, x + width / 2, y + height / 2);
      }
      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Floor
      ctx.fillStyle = '#6c757d';
      ctx.fillRect(0, canvas.height - 20, canvas.width, 20);

      // Falling items
      ctx.font = '28px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      for (const item of items) {
        ctx.fillText(item.symbol, item.x + item.size / 2, item.y);
      }

      // Dog
      let dogSprite = '🐶';
      if (dog.scared) dogSprite = '😱';
      else if (dog.stunTimer > 0) dogSprite = '😵';
      renderSprite(dogSprite, dog.x, dog.y, dog.width, dog.height, dog.facingLeft, 42);

      // Cat
      const isMega = megaTimeLeft > 0;
      if (isMega) {
        // Draw rainbow glow ring around Mega Cat
        ctx.save();
        ctx.strokeStyle = `hsl(${(Date.now() / 5) % 360}, 100%, 55%)`;
        ctx.lineWidth = 6;
        ctx.beginPath();
        ctx.arc(cat.x + cat.width / 2, cat.y + cat.height / 2, cat.width / 2 + 6, 0, Math.PI * 2);
