        ctx.restore();
        renderSprite('🦁', cat.x, cat.y, cat.width, cat.height, cat.facingLeft, 80);
      } else {
        renderSprite('🐱', cat.x, cat.y, cat.width, cat.height, cat.facingLeft, 42);
      }

      // Floater popups
      for (const a of alerts) {
        ctx.save();
        ctx.globalAlpha = Math.max(0, a.alpha);
        ctx.fillStyle = a.color;
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(a.text, a.x, a.y);
        ctx.restore();
      }
    }

    function gameLoop() {
      if (!isPlaying) return;
      update();
      render();
      requestAnimationFrame(gameLoop);
    }

    startBtn.addEventListener('click', resetGame);
  </script>
</body>
</html>
