      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Floor
      ctx.fillStyle = '#6c757d';
      ctx.fillRect(0, canvas.height - 20, canvas.width, 20);

      // Laser Beams
      for (const l of lasers) {
        ctx.save();
        ctx.shadowBlur = 10;
        ctx.shadowColor = l.isMega ? '#00f5d4' : '#ff0054';
        ctx.fillStyle = l.isMega ? '#00f5d4' : '#ff0054';
        ctx.fillRect(l.x - l.width / 2, l.y, l.width, l.height);
        ctx.restore();
      }

      // Spark Particles
      for (const s of sparks) {
        ctx.save();
        ctx.fillStyle = s.color;
        ctx.fillRect(s.x, s.y, 4, 4);
        ctx.restore();
      }

      // Items
      ctx.font = '28px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      for (const item of items) {
        ctx.fillText(item.symbol, item.x + item.size / 2, item.y);
      }

      // Dog
      let dogSprite = '🐶';
      if (dog.scared) dogSprite = '😱';
      else if (dog.stunTimer > 0) dogSprite = '😵';
      renderSprite(dogSprite, dog.x, dog.y, dog.width, dog.height, dog.facingLeft, 42);

      // Cat
      const isMega = megaTimeLeft > 0;
      if (isMega) {
        ctx.save();
        ctx.strokeStyle = `hsl(${(Date.now() / 5) % 360}, 100%, 55%)`;
        ctx.lineWidth = 6;
        ctx.beginPath();
        ctx.arc(cat.x + cat.width / 2, cat.y + cat.height / 2, cat.width / 2 + 6, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
        renderSprite('🦁', cat.x, cat.y, cat.width, cat.height, cat.facingLeft, 80);
      } else {
        renderSprite('🐱', cat.x, cat.y, cat.width, cat.height, cat.facingLeft, 42);
      }

      // Alerts
      for (const a of alerts) {
        ctx.save();
        ctx.globalAlpha = Math.max(0, a.alpha);
        ctx.fillStyle = a.color;
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(a.text, a.x, a.y);
        ctx.restore();
      }
    }

    function gameLoop() {
      if (!isPlaying) return;
      update();
      render();
      requestAnimationFrame(gameLoop);
    }

    startBtn.addEventListener('click', resetGame);
  </script>
</body>
</html>
