  <div id="game-container">
    <canvas id="gameCanvas" width="400" height="550"></canvas>
    <div id="ui-layer">
      <h1 id="title-text">🐱 Fish Catcher</h1>
      <p id="desc-text">Move your mouse, touch, or use ⬅️ ➡️ keys.<br>Catch fish, avoid bombs!</p>
      <button id="start-btn">Play Game</button>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const uiLayer = document.getElementById('ui-layer');
    const startBtn = document.getElementById('start-btn');
    const titleText = document.getElementById('title-text');
    const descText = document.getElementById('desc-text');

    let score = 0;
    let lives = 3;
    let gameOver = true;
    let items = [];
    let spawnTimer = 0;
    let speedMultiplier = 1;

    const cat = {
      x: canvas.width / 2,
      y: canvas.height - 50,
      size: 48,
      speed: 7,
      movingLeft: false,
      movingRight: false
    };

    const itemTypes = [
      { type: 'fish', emoji: '🐟', points: 10, isHazard: false, weight: 6 },
      { type: 'golden', emoji: '🐠', points: 25, isHazard: false, weight: 2 },
      { type: 'squid', emoji: '🦑', points: 15, isHazard: false, weight: 2 },
      { type: 'bomb', emoji: '💣', points: 0, isHazard: true, weight: 3 }
    ];

    function getRandomItem() {
      const pool = [];
      itemTypes.forEach(item => {
        for (let i = 0; i < item.weight; i++) pool.push(item);
      });
      const selected = pool[Math.floor(Math.random() * pool.length)];
      return {
        ...selected,
        x: Math.random() * (canvas.width - 40) + 20,
        y: -30,
        speed: (Math.random() * 2 + 2.5) * speedMultiplier,
        size: 32
      };
    }

    function resetGame() {
      score = 0;
      lives = 3;
      speedMultiplier = 1;
      items = [];
      cat.x = canvas.width / 2;
      gameOver = false;
      uiLayer.classList.add('hidden');
      requestAnimationFrame(gameLoop);
    }

    function endGame() {
      gameOver = true;
      titleText.textContent = 'Game Over!';
      descText.innerHTML = `You caught <b>${score}</b> points of seafood!`;
      startBtn.textContent = 'Play Again';
      uiLayer.classList.remove('hidden');
    }

    // Input handlers
    window.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowLeft' || e.key === 'a') cat.movingLeft = true;
      if (e.key === 'ArrowRight' || e.key === 'd') cat.movingRight = true;
    });

    window.addEventListener('keyup', (e) => {
      if (e.key === 'ArrowLeft' || e.key === 'a') cat.movingLeft = false;
      if (e.key === 'ArrowRight' || e.key === 'd') cat.movingRight = false;
    });

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      cat.x = e.clientX - rect.left;
    });

    canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      cat.x = e.touches[0].clientX - rect.left;
    }, { passive: false });

    startBtn.addEventListener('click', resetGame);

    function update() {
      // Cat horizontal bounds
      if (cat.movingLeft) cat.x -= cat.speed;
      if (cat.movingRight) cat.x += cat.speed;
      cat.x = Math.max(cat.size / 2, Math.min(canvas.width - cat.size / 2, cat.x));

      // Gradual difficulty curve
      speedMultiplier = 1 + score / 300;

      // Spawn items
      spawnTimer++;
      if (spawnTimer > Math.max(25, 60 - Math.floor(score / 20))) {
        items.push(getRandomItem());
        spawnTimer = 0;
      }

      // Update falling items
      for (let i = items.length - 1; i >= 0; i--) {
        const item = items[i];
        item.y += item.speed;

        // Catch collision
        const dist = Math.hypot(item.x - cat.x, item.y - cat.y);
        if (dist < 36) {
          if (item.isHazard) {
            lives--;
            if (lives <= 0) return endGame();
          } else {
            score += item.points;
          }
          items.splice(i, 1);
          continue;
        }

        // Missed bottom edge
        if (item.y > canvas.height + 20) {
          if (!item.isHazard) {
            lives--;
            if (lives <= 0) return endGame();
          }
          items.splice(i, 1);
        }
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Floor / grass strip
      ctx.fillStyle = '#65c365';
      ctx.fillRect(0, canvas.height - 20, canvas.width, 20);

      // Draw Cat
      ctx.font = `${cat.size}px serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🐱', cat.x, cat.y);

      // Draw Items
      items.forEach(item => {
        ctx.font = `${item.size}px serif`;
        ctx.fillText(item.emoji, item.x, item.y);
      });

      // HUD / Scoreboard
      ctx.fillStyle = '#333';
      ctx.font = 'bold 18px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(`Score: ${score}`, 16, 30);

      ctx.textAlign = 'right';
      ctx.fillText(`Lives: ${'❤️'.repeat(Math.max(0, lives))}`, canvas.width - 16, 30);
    }

    function gameLoop() {
      if (gameOver) return;
      update();
      render();
      requestAnimationFrame(gameLoop);
    }
  </script>
</body>
</html>
