    // Item pool with rare 100-pt Rainbow Fish
    const itemTypes = [
      { type: 'fish', display: '🐟', points: 10, weight: 6, isRainbow: false },
      { type: 'golden', display: '🐠', points: 25, weight: 3, isRainbow: false },
      { type: 'shrimp', display: '🦐', points: 20, weight: 3, isRainbow: false },
      { type: 'squid', display: '🦑', points: 15, weight: 2, isRainbow: false },
      { type: 'rainbow', display: '🐟', points: 100, weight: 1, isRainbow: true }
    ];

    function getRandomItem() {
      const pool = [];
      itemTypes.forEach(item => {
        for (let i = 0; i < item.weight; i++) pool.push(item);
      });
      const selected = pool[Math.floor(Math.random() * pool.length)];
      return {
        ...selected,
        x: Math.random() * (canvas.width - 60) + 30,
        y: -30,
        speed: (Math.random() * 1.6 + 2.2) * speedMultiplier,
        size: selected.isRainbow ? 40 : 32,
        wobble: Math.random() * Math.PI * 2
      };
    }

    function resetGame() {
      score = 0;
      lives = 3;
      speedMultiplier = 1;
      items = [];
      popups = [];
      cat.x = canvas.width / 2;
      gameOver = false;
      uiLayer.classList.add('hidden');
      requestAnimationFrame(gameLoop);
    }

    function endGame() {
      gameOver = true;
      titleText.textContent = 'Snack Time Over!';
      descText.innerHTML = `Your pink kitty caught <b>${score}</b> points of seafood!`;
      startBtn.textContent = 'Play Again';
      uiLayer.classList.remove('hidden');
    }

    // Input handlers
    window.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowLeft' || e.key === 'a') cat.movingLeft = true;
      if (e.key === 'ArrowRight' || e.key === 'd') cat.movingRight = true;
    });

    window.addEventListener('keyup', (e) => {
      if (e.key === 'ArrowLeft' || e.key === 'a') cat.movingLeft = false;
      if (e.key === 'ArrowRight' || e.key === 'd') cat.movingRight = false;
    });

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      cat.x = e.clientX - rect.left;
    });

    canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      cat.x = e.touches[0].clientX - rect.left;
    }, { passive: false });

    startBtn.addEventListener('click', resetGame);

    function update() {
      if (cat.movingLeft) cat.x -= cat.speed;
      if (cat.movingRight) cat.x += cat.speed;
      cat.x = Math.max(cat.size / 2, Math.min(canvas.width - cat.size / 2, cat.x));

      speedMultiplier = 1 + score / 550;

      spawnTimer++;
      if (spawnTimer > Math.max(28, 65 - Math.floor(score / 35))) {
        items.push(getRandomItem());
        spawnTimer = 0;
      }

      // Update floating score text
      for (let i = popups.length - 1; i >= 0; i--) {
        popups[i].y -= 1.5;
        popups[i].alpha -= 0.025;
        if (popups[i].alpha <= 0) popups.splice(i, 1);
      }

      // Update items
      for (let i = items.length - 1; i >= 0; i--) {
        const item = items[i];
        item.y += item.speed;
        item.wobble += 0.08;

        // Catch collision
        const dist = Math.hypot(item.x - cat.x, item.y - cat.y);
        if (dist < 40) {
          score += item.points;

          popups.push({
            text: `+${item.points}`,
            x: item.x,
            y: item.y - 10,
            color: item.isRainbow ? '#ff007f' : '#2e7d32',
            isBig: item.isRainbow,
            alpha: 1
          });

          items.splice(i, 1);
          continue;
        }

        // Missed item
        if (item.y > canvas.height + 25) {
          lives--;
          if (lives <= 0) return endGame();
          items.splice(i, 1);
        }
      }
    }

    function drawPinkCat(x, y) {
      ctx.save();
      ctx.translate(x, y);

      // Ears
      ctx.fillStyle = '#ff80bf';
      ctx.beginPath();
      ctx.moveTo(-18, -10);
      ctx.lineTo(-12, -26);
      ctx.lineTo(-4, -16);
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(4, -16);
      ctx.lineTo(12, -26);
      ctx.lineTo(18, -10);
      ctx.fill();

      // Inner ears
      ctx.fillStyle = '#ffe6f0';
      ctx.beginPath();
      ctx.moveTo(-15, -11);
      ctx.lineTo(-12, -21);
      ctx.lineTo(-6, -15);
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(6, -15);
      ctx.lineTo(12, -21);
      ctx.lineTo(15, -11);
      ctx.fill();

      // Head
      ctx.fillStyle = '#ffa6d2';
      ctx.beginPath();
      ctx.arc(0, 0, 20, 0, Math.PI * 2);
      ctx.fill();

      // Cheeks
      ctx.fillStyle = '#ff66b2';
      ctx.beginPath();
      ctx.arc(-11, 4, 3.5, 0, Math.PI * 2);
      ctx.arc(11, 4, 3.5, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = '#4a2c3a';
      ctx.beginPath();
      ctx.arc(-7, -2, 2.5, 0, Math.PI * 2);
      ctx.arc(7, -2, 2.5, 0, Math.PI * 2);
      ctx.fill();

      // Nose
      ctx.fillStyle = '#e60073';
      ctx.beginPath();
      ctx.arc(0, 3, 2, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }

    function drawRainbowFish(item) {
      ctx.save();
      ctx.translate(item.x, item.y);

      // Shimmering rainbow glow halo
      const time = Date.now() / 200;
      const glowGrad = ctx.createRadialGradient(0, 0, 5, 0, 0, 26);
      glowGrad.addColorStop(0, 'rgba(255, 255, 255, 0.9)');
      glowGrad.addColorStop(0.5, 'rgba(255, 180, 230, 0.6)');
      glowGrad.addColorStop(1, 'rgba(150, 220, 255, 0)');
      ctx.fillStyle = glowGrad;
      ctx.beginPath();
      ctx.arc(0, 0, 26, 0, Math.PI * 2);
      ctx.fill();

      // Rainbow fish icon
      ctx.font = `${item.size}px serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🌈', -10, -4);
      ctx.fillText('🐟', 10, 4);

      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Floor
      ctx.fillStyle = '#9bd49b';
      ctx.fillRect(0, canvas.height - 18, canvas.width, 18);

      // Cat
      drawPinkCat(cat.x, cat.y);

      // Items
      items.forEach(item => {
        if (item.isRainbow) {
          drawRainbowFish(item);
        } else {
          ctx.font = `${item.size}px serif`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(item.display, item.x, item.y);
        }
      });

      // Floating points popups
      popups.forEach(pop => {
        ctx.save();
        ctx.globalAlpha = pop.alpha;
        ctx.fillStyle = pop.color;
        ctx.font = pop.isBig ? 'bold 22px sans-serif' : 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(pop.text, pop.x, pop.y);
        ctx.restore();
      });

      // HUD
      ctx.fillStyle = '#4a2c3a';
      ctx.font = 'bold 18px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(`Score: ${score}`, 16, 30);

      ctx.textAlign = 'right';
      ctx.fillText(`Lives: ${'💖'.repeat(Math.max(0, lives))}`, canvas.width - 16, 30);
    }

    function gameLoop() {
      if (gameOver) return;
      update();
      render();
      requestAnimationFrame(gameLoop);
    }
  </script>
</body>
</html>
